INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_ADJECTIVE','Jurchen');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_AGUDA_HEADING_1','Uniting the Jurchen');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_AGUDA_LIVED','1068–1123');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_AGUDA_NAME','Wanyan Aguda');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_AGUDA_SUBTITLE','Emperor Taizu of Jin');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_AGUDA_TEXT_1','Wanyan Aguda (1068–1123), posthumously Emperor Taizu of Jin, led the Wanyan clan in rebellion against the Liao and proclaimed the Jin dynasty in 1115. His cavalry campaigns secured the foundations of a northern empire. He died before the conquest of the Northern Song court. The leader portrait is an original artistic interpretation, not a surviving likeness.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_AGUDA_TITLES_1','Founder of the Jin Dynasty');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_BED_CROSSBOW','Bed Crossbow');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_BED_CROSSBOW_HELP','Mathematics and Machine Workshop; 100 Production; 9 melee/15 ranged; Range 2. A second bolt deals 35% of actual primary damage to the target (nonlethal). +25% against melee infantry; no inherited city siege bonus or setup. Upgrades to Trebuchet.');
