INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_CITY_9','Dongjing');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_CIV','The Jin Dynasty');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_CIV5_HEADING_1','The Jurchen Empire');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_CIV5_TEXT_1','The Jurchen Jin Dynasty (1115–1234) arose in northeastern Asia. Wanyan Aguda united Jurchen communities against Liao rule and founded a new imperial state in 1115. The Jin conquered northern Song territory in the 1120s, developing institutions that combined Jurchen military households with Chinese civil administration. Its capitals included Huining, Zhongdu and later Kaifeng. Warfare against the Southern Song and the Mongols reshaped the dynasty until its fall in 1234. This civilization adapts the interdependent Jin economy and cavalry systems of Age of Empires IV: Yue Fei''s Legacy; it is not a Chinese civilization variant.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_CIV_PEDIA','The Jurchen Jin Dynasty (1115–1234) arose in northeastern Asia. Wanyan Aguda united Jurchen communities against Liao rule and founded a new imperial state in 1115. The Jin conquered northern Song territory in the 1120s, developing institutions that combined Jurchen military households with Chinese civil administration. Its capitals included Huining, Zhongdu and later Kaifeng. Warfare against the Southern Song and the Mongols reshaped the dynasty until its fall in 1234. This civilization adapts the interdependent Jin economy and cavalry systems of Age of Empires IV: Yue Fei''s Legacy; it is not a Chinese civilization variant.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_DAWN','Wanyan Aguda, the riders of the northeast await your command. Your people will build an empire from swift labor, fertile pasture and disciplined cavalry.[NEWLINE][NEWLINE]Choose the foundations of your dynasty. Let Horses gather in your Grasslands, bring independent settlements into tribute, and call the Meng''an Mouke to defend the frontier. Will you spend your strength today, or preserve it for the battles still to come?');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_DEFENDER','Meng''an Mouke Defender');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_DEFENDER_HELP','Early automatic emplacement defender. 16 Strength; 4 Movement. Home leash, no city capture and finite lifetime; cannot be trained or upgraded.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_DIPLO_ATTACKED_1','You have summoned the strength of the north.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_DIPLO_DECLAREWAR_1','The riders are ready. Your borders will not stop them.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_DIPLO_DEFEATED_1','An empire falls. Its people endure.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_DIPLO_FIRST_GREETING_1','The Jin welcome an envoy who speaks with purpose.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_DIPLO_GREETING_HOSTILE_HELLO_1','You have tested our patience.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_DIPLO_GREETING_NEUTRAL_HELLO_1','Speak. The court is listening.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_DIPLO_GREETING_POLITE_HELLO_1','May trade prosper between our peoples.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_DIPLO_PEACE_MADE_BY_HUMAN_GRACIOUS_1','Let the horses rest and the fields recover.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_DIPLO_TRADE_ACCEPT_GENEROUS_1','Our envoys accept this exchange.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_DRAGON_PAVILION','Dragon Pavilion');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_DRAGON_PAVILION_HELP','One free Emissary (deferred if capped/blocked); +100% Emissary Production in all Jin cities, equivalent to half cost. All current/future Jin cities gain Meng''an Mouke defenses.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_EMISSARY','Emissary');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_EMISSARY_HELP','120 Production; 3 Movement; noncombat. Available after the second completed Landmark; cap 2. May enter neutral territory. Establish Tributary adjacent to an independent peaceful City-State capital, or Bribe nearby hostile military units. Dragon Pavilion halves production cost.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_ERUPTOR','Eruptor');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_ERUPTOR_HELP','Chemistry; 260 Production; 18 melee/42 ranged; Range 1; 2 Movement. Short-range blast deals 10% of actual primary damage to up to 3 adjacent hostile combat units.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_FLOWER_PAGODA','Flower Pagoda');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_FLOWER_PAGODA_HELP','Place one movable Flower Garden from the Dynasty panel: radius 2, +25% worker speed and +15% non-siege military strength. Relocation cooldown 5 Standard turns.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_GARDEN','Flower Garden');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_GRASSLAND','Grassland');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_GREAT_PASTURE','Great Pasture');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_GREAT_PASTURE_HELP','Separate 5-Horse stockpile in this city, also acts as a War Stable. In addition, completion grants the normal chosen Grassland.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_GREAT_WALL_BASTION','Great Wall Bastion');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_GREAT_WALL_BASTION_HELP','Capital gains 1,000 defense (10 displayed strength), +25% ranged strike, two defender slots and one automatic 20-HP Bed Crossbow shot per owner-turn.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_GRENADIER','Mounted Grenadier');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_GRENADIER_HELP','Chemistry automatic emplacement defender. 24 melee/32 ranged; Range 2; 4 Movement. 20% bounded collateral, home leash and finite lifetime; cannot be trained or upgraded.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_GROVE','Pagoda Grove');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_IRON_PAGODA','Iron Pagoda');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_IRON_PAGODA_HELP','Horseback Riding; 145 Production; 19 Strength; 3 Movement. +15% defense against melee combat classes. After attacking a unit, deals 15% of actual primary damage to at most 3 adjacent hostile combat units. Requires Horses. Upgrades through the mounted line.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_LEADER','Wanyan Aguda');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_LEADER_PEDIA','Wanyan Aguda (1068–1123), posthumously Emperor Taizu of Jin, led the Wanyan clan in rebellion against the Liao and proclaimed the Jin dynasty in 1115. His cavalry campaigns secured the foundations of a northern empire. He died before the conquest of the Northern Song court. The leader portrait is an original artistic interpretation, not a surviving likeness.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_MACHINE_WORKSHOP','Machine Workshop');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_MACHINE_WORKSHOP_HELP','Enables Bed Crossbows in this city. Retains Barracks training experience.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_MOHE','Mohe Tribesman');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_MOHE_HELP','Horseback Riding; 75 Production; 8 melee/9 ranged Strength; Range 2; 5 Movement. May move after one attack. +15% against melee infantry. Benefits from ranged cavalry Horse HP.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_MONASTERY','Jin Monastery');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_MONASTERY_HELP','Generates Faith and supports nearby Karma gathering after Mountain Hall. Mountain Hall halves its production cost.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_MONASTERY_POLICY','Mountain Hall monasteries');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_MOUNTAIN_HALL','Mountain Hall');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_MOUNTAIN_HALL_HELP','Acts as a Monastery; +100% Monastery Production. Worked tiles and nearby workers generate Karma; deaths remove 25. At 1,000, reset and bless for 4 turns: +1 Farm Food, +4 Faith, +10 city healing and +25% city ranged attacks.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_MOUNTED_VILLAGER','Mounted Villager');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_MOUNTED_VILLAGER_HELP','110 Production; 3 Movement; 150% of the active Worker base work rate. All Worker builds/routes/repair. Noncombat; cap 20 plus 3 per active Tributary. Ordinary Workers remain available. Uses a borrowed mounted model.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_NEST_OF_BEES','Nest of Bees');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_NEST_OF_BEES_HELP','Machinery; 170 Production; 12 melee/26 ranged; Range 2. Anti-unit field artillery using the built-in Catapult model. No Korean DLC dependency; no inherited city siege bonus.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_PAGODA_FOREST','Pagoda Forest');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_PAGODA_FOREST_HELP','Generates one Pagoda Grove each 5 Standard turns, up to 15 empire-wide and 5 around each city. +1 Production on worked Groves; nearby hostile units lose 1 Movement once per turn.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_PAVILION_DISCOUNT','Pavilion Discount');
