INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_PROMO_ZHANMA','Zhanma');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_REINDEER_TRADER','Reindeer Trader');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_REINDEER_TRADER_HELP','90 Production; 2 Movement; retains the active Caravan trade behavior and route limits. With any active Tributary, one +15% native modifier applies to outgoing international income, including Gold and native non-Gold trade yields; never stacks per Tributary.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_SHORT','Jin');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_SPY_1','Wanyan Zonghan');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_SPY_10','Wulinda');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_SPY_2','Wanyan Xiyin');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_SPY_3','Wanyan Zongwang');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_SPY_4','Wanyan Lou Shi');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_SPY_5','Wanyan Yinshu');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_SPY_6','Sheng');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_SPY_7','Pucha');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_SPY_8','Hesheri');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_SPY_9','Tangkuo');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_STRATEGY','Choose Grassland sites within two plots of cities with War Stables. Retained Horses protect the entire mounted army; spending them buys tempo at the cost of health. Mounted Villagers are fast but expensive. Escort Emissaries, cultivate City-State Tributaries and use Bribe to disrupt formations. Each Landmark pair permanently locks one path. Fortification defenders expire and must remain near their home.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_TRACTION_TREBUCHET','Traction Trebuchet');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_TRACTION_TREBUCHET_HELP','Physics; 125 Production; 12 melee/14 ranged; Range 2. Conventional Trebuchet city siege behavior and upgrade path, with Jin identity.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_TRADE_POLICY','Tributary trade');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_TRAIT','Jurchen Legacy');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_TRAIT_HELP','Train Mounted Villagers. Build one of two Landmarks each in Classical, Medieval and Renaissance; each grants one chosen Grassland. Stockpile up to 5 Horses per Grassland: each gives cavalry +2 melee/+1 ranged maximum HP, or spend one plus 65% Gold to recruit cavalry near a War Stable. Emissaries establish independent City-State Tributaries and bribe hostile troops into Barbarian rebellion. Manage Jin systems in the crimson-and-gold Dynasty panel.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_TRIBUTE','Tribute');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_UP_BED_EMPLACEMENT','Bed Crossbow Emplacement');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_UP_BED_EMPLACEMENT_HELP','Emplacements fire one automatic 12-HP defensive shot per owner-turn.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_UP_COLLECTIVE_HUNTING','Collective Hunting');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_UP_COLLECTIVE_HUNTING_HELP','+1 Food on Camps in Jin cities.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_UP_DRAFT_HORSES','Draft Horses');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_UP_DRAFT_HORSES_HELP','Mounted Villagers gain +25% work rate; cavalry gain +1 Movement.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_UP_FLYING_FIRE','Flying Fire Battalions');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_UP_FLYING_FIRE_HELP','Eruptors and Mounted Grenadiers gain +15% ranged attack.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_UP_HEAVEN_THUNDER','Heaven Shaking Thunder');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_UP_HEAVEN_THUNDER_HELP','Eruptor/Grenadier collateral damage increases by 50%.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_UP_MENGAN_EMPLACEMENT','Meng''an Mouke Emplacement');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_UP_MENGAN_EMPLACEMENT_HELP','Cities and owned Forts/Citadels deploy temporary cavalry defenders.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_UP_MOHE_ANCESTRY','Mohe Ancestry');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_JIN_UP_MOHE_ANCESTRY_HELP','Mohe Tribesmen gain +15% ranged attack.');
